function drawAnalysisChart(){const visible=analysisTraces.filter(trace=>trace.visible);if(!visible.length){$('#chart').innerHTML='';return}const metricName=$('#chartMetric').value,w=900,h=300,pad=45,samples=[];visible.forEach(trace=>trace.points.forEach(point=>{const xValue=point[xFieldFor(trace.axis)],yValue=point[metricName];if(xValue!==null&&Number.isFinite(yValue))samples.push({x:xValue,y:yValue})}));if(!samples.length){$('#chart').innerHTML=`<text class="axis-label" x="45" y="70">${language==='zh'?'此指標沒有可比較的有效數值':'No comparable values for this metric'}</text>`;return}const xmin=Math.min(...samples.map(sample=>sample.x)),xmax=Math.max(...samples.map(sample=>sample.x)),rawYMin=Math.min(...samples.map(sample=>sample.y)),rawYMax=Math.max(...samples.map(sample=>sample.y)),margin=Math.max((rawYMax-rawYMin)*.15,.5),ymin=rawYMin-margin,ymax=rawYMax+margin,x=value=>pad+(value-xmin)/(xmax-xmin||1)*(w-pad*2),y=value=>h-pad-(value-ymin)/(ymax-ymin||1)*(h-pad*2);let html='';for(let i=0;i<5;i++){const yy=pad+i*(h-pad*2)/4;html+=`<line class="grid-line" x1="${pad}" y1="${yy}" x2="${w-pad}" y2="${yy}"/><text class="axis-label" x="5" y="${yy+4}">${(ymax-i*(ymax-ymin)/4).toFixed(1)}</text>`}visible.forEach(trace=>{const xField=xFieldFor(trace.axis),dash=trace.lineStyle==='dash'?'10 7':trace.lineStyle==='dot'?'2 6':'none';let segment=[];const flush=()=>{if(segment.length){html+=`<polyline fill="none" stroke="${trace.color}" stroke-width="3" stroke-dasharray="${dash}" stroke-linecap="round" points="${segment.map(point=>`${x(point[xField])},${y(point[metricName])}`).join(' ')}"/>`;segment=[]}};trace.points.forEach(point=>{const valid=point.valid&&point[xField]!==null&&Number.isFinite(point[metricName]);if(valid)segment.push(point);else flush()});flush();trace.points.forEach(point=>{if(point[xField]===null||!Number.isFinite(point[metricName]))return;const cx=x(point[xField]),cy=y(point[metricName]),fill=point.valid?trace.color:'#f05261',title=`${trace.name} | x=${point[xField]} | ${metricName}=${point[metricName]} | EVM=${point.evm_all_db} dB | Power=${point.burst_power_dbm} dBm | FreqErr=${point.frequency_error_hz} Hz | ${point.valid?'VALID':'INVALID'}`,shape=trace.pointShape==='square'?`<rect x="${cx-4}" y="${cy-4}" width="8" height="8" rx="1"`:trace.pointShape==='diamond'?`<polygon points="${cx},${cy-5} ${cx+5},${cy} ${cx},${cy+5} ${cx-5},${cy}"`:`<circle cx="${cx}" cy="${cy}" r="4"`;html+=`${shape} data-chart-point="true" data-tooltip="${escapeHtml(title)}" fill="${fill}" stroke="${trace.color}"><title>${escapeHtml(title)}</title></${trace.pointShape==='square'?'rect':trace.pointShape==='diamond'?'polygon':'circle'}>`})});$('#chart').innerHTML=html}
$('#chartMetric').onchange=()=>{analysisTraces.length?drawAnalysisChart():(latest.length&&drawChart(latest,latestAxis))};
function downloadBlob(filename,blob){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),0)}
$('#exportSvg').onclick=()=>{const svg=$('#chart').cloneNode(true);svg.setAttribute('xmlns','http://www.w3.org/2000/svg');downloadBlob('cmp180-comparison.svg',new Blob([new XMLSerializer().serializeToString(svg)],{type:'image/svg+xml'}))};
$('#exportPng').onclick=()=>{const svg=$('#chart').cloneNode(true);svg.setAttribute('xmlns','http://www.w3.org/2000/svg');const blob=new Blob([new XMLSerializer().serializeToString(svg)],{type:'image/svg+xml'}),url=URL.createObjectURL(blob),image=new Image();image.onload=()=>{const canvas=document.createElement('canvas');canvas.width=1800;canvas.height=600;const context=canvas.getContext('2d');context.fillStyle=getComputedStyle(document.documentElement).getPropertyValue('--console-surface')||'#fff';context.fillRect(0,0,canvas.width,canvas.height);context.drawImage(image,0,0,canvas.width,canvas.height);canvas.toBlob(png=>{if(png)downloadBlob('cmp180-comparison.png',png)},'image/png');URL.revokeObjectURL(url)};image.src=url};
$('#exportCompareCsv').onclick=()=>{const metricName=$('#chartMetric').value,rows=[['trace','valid','frequency_hz','generator_power_dbm',metricName,'measurement_state']];analysisTraces.forEach(trace=>trace.points.forEach(point=>rows.push([trace.name,point.valid,point.frequency_hz,point.generator_power_dbm,point[metricName],point.measurement_state])));const csv=rows.map(row=>row.map(value=>`"${String(value??'').replaceAll('"','""')}"`).join(',')).join('\r\n');downloadBlob('cmp180-comparison.csv',new Blob([csv],{type:'text/csv;charset=utf-8'}))};
const chartTooltip=document.createElement('div');chartTooltip.className='chart-hover-tooltip';chartTooltip.hidden=true;document.querySelector('.chart-card').append(chartTooltip);
$('#chart').addEventListener('pointermove',event=>{const svg=$('#chart'),points=[...svg.querySelectorAll('[data-chart-point]')];if(!points.length)return;let nearest=null,distance=Infinity;points.forEach(point=>{const box=point.getBoundingClientRect(),dx=event.clientX-(box.left+box.width/2),dy=event.clientY-(box.top+box.height/2),candidate=Math.hypot(dx,dy);if(candidate<distance){distance=candidate;nearest=point}});svg.querySelectorAll('.chart-crosshair,.chart-focus-ring').forEach(item=>item.remove());if(!nearest||distance>70){chartTooltip.hidden=true;return}const ns='http://www.w3.org/2000/svg',cx=Number(nearest.getAttribute('cx')??nearest.getBBox().x+nearest.getBBox().width/2),cy=Number(nearest.getAttribute('cy')??nearest.getBBox().y+nearest.getBBox().height/2),vertical=document.createElementNS(ns,'line'),horizontal=document.createElementNS(ns,'line'),ring=document.createElementNS(ns,'circle');vertical.setAttribute('class','chart-crosshair');vertical.setAttribute('x1',cx);vertical.setAttribute('x2',cx);vertical.setAttribute('y1','35');vertical.setAttribute('y2','255');horizontal.setAttribute('class','chart-crosshair');horizontal.setAttribute('x1','45');horizontal.setAttribute('x2','855');horizontal.setAttribute('y1',cy);horizontal.setAttribute('y2',cy);ring.setAttribute('class','chart-focus-ring');ring.setAttribute('cx',cx);ring.setAttribute('cy',cy);ring.setAttribute('r','7');svg.append(vertical,horizontal,ring);chartTooltip.innerHTML=`<strong>${language==='zh'?'量測點':'Measurement point'}</strong>${escapeHtml(nearest.dataset.tooltip).replaceAll(' | ','<br>')}`;const card=document.querySelector('.chart-card').getBoundingClientRect();chartTooltip.style.left=`${Math.min(event.clientX-card.left,card.width-330)}px`;chartTooltip.style.top=`${Math.max(8,event.clientY-card.top-24)}px`;chartTooltip.hidden=false});
$('#chart').addEventListener('pointerleave',()=>{chartTooltip.hidden=true;$('#chart').querySelectorAll('.chart-crosshair,.chart-focus-ring').forEach(item=>item.remove())});

